CREATE DATABASE financial_performance;

SELECT COUNT(*) AS total_transactions
FROM `03_clean_transactions`;

# 1 What is the total revenue generated by the company?

SELECT
    SUM(Amount) AS Total_Revenue
FROM `03_clean_transactions`
WHERE Transaction_Type = 'Revenue';


# 2 What are the company's total operating expenses?

SELECT
    SUM(Amount) AS Total_Expenses
FROM `03_clean_transactions`
WHERE Transaction_Type = 'Expense';


# 3 How much profit remains after deducting expenses from revenue?

SELECT
    SUM(CASE
        WHEN Transaction_Type = 'Revenue' THEN Amount
        WHEN Transaction_Type = 'Expense' THEN -Amount
        ELSE 0
    END) AS Net_Profit
FROM `03_clean_transactions`;


# 4 What percentage of revenue does the company retain as profit?

SELECT
    ROUND(
        SUM(CASE
            WHEN Transaction_Type = 'Revenue' THEN Amount
            WHEN Transaction_Type = 'Expense' THEN -Amount
            ELSE 0
        END) * 100.0
        / SUM(CASE
            WHEN Transaction_Type = 'Revenue' THEN Amount
            ELSE 0
        END),
        2
    ) AS Net_Profit_Margin_Percent
FROM `03_clean_transactions`;


# 5 Which months generated the highest revenue?

SELECT
    DATE_FORMAT(`Date`, '%Y-%m') AS Revenue_Month,
    ROUND(SUM(Amount), 2) AS Monthly_Revenue
FROM `03_clean_transactions`
WHERE Transaction_Type = 'Revenue'
  AND `Date` <> 'Unknown'
GROUP BY DATE_FORMAT(`Date`, '%Y-%m')
ORDER BY Monthly_Revenue DESC;


# 6 Which departments have the highest expenses?

SELECT
    Department,
    ROUND(SUM(Amount), 2) AS Total_Expenses
FROM `03_clean_transactions`
WHERE Transaction_Type = 'Expense'
GROUP BY Department
ORDER BY Total_Expenses DESC;


# 7 Which products generate the highest profit?


SELECT
    Product,
    ROUND(
        SUM(
            CASE
                WHEN Transaction_Type = 'Revenue' THEN Amount
                WHEN Transaction_Type = 'Expense' THEN -Amount
                ELSE 0
            END
        ), 2
    ) AS Product_Profit
FROM `03_clean_transactions`
GROUP BY Product
ORDER BY Product_Profit DESC;


# 8 Monthly Revenue vs Expenses?


SELECT
    DATE_FORMAT(`Date`, '%Y-%m') AS Analysis_Month,

    ROUND(SUM(
        CASE
            WHEN Transaction_Type = 'Revenue'
            THEN Amount ELSE 0
        END
    ), 2) AS Monthly_Revenue,

    ROUND(SUM(
        CASE
            WHEN Transaction_Type = 'Expense'
            THEN Amount ELSE 0
        END
    ), 2) AS Monthly_Expenses,

    ROUND(SUM(
        CASE
            WHEN Transaction_Type = 'Revenue' THEN Amount
            WHEN Transaction_Type = 'Expense' THEN -Amount
            ELSE 0
        END
    ), 2) AS Monthly_Profit

FROM `03_clean_transactions`
WHERE `Date` <> 'Unknown'
GROUP BY DATE_FORMAT(`Date`, '%Y-%m')
ORDER BY Analysis_Month;


# 9 hich regions contribute the most revenue?


SELECT
    Region,
    ROUND(SUM(Amount), 2) AS Total_Revenue,
    COUNT(*) AS Revenue_Transactions
FROM `03_clean_transactions`
WHERE Transaction_Type = 'Revenue'
GROUP BY Region
ORDER BY Total_Revenue DESC;


# 10 Is financial performance improving or declining?


WITH Monthly_Performance AS (
    SELECT
        DATE_FORMAT(`Date`, '%Y-%m') AS Analysis_Month,

        SUM(CASE
            WHEN Transaction_Type = 'Revenue'
            THEN Amount ELSE 0
        END) AS Revenue,

        SUM(CASE
            WHEN Transaction_Type = 'Expense'
            THEN Amount ELSE 0
        END) AS Expenses,

        SUM(CASE
            WHEN Transaction_Type = 'Revenue' THEN Amount
            WHEN Transaction_Type = 'Expense' THEN -Amount
            ELSE 0
        END) AS Net_Profit

    FROM `03_clean_transactions`
    WHERE `Date` <> 'Unknown'
    GROUP BY DATE_FORMAT(`Date`, '%Y-%m')
)

SELECT
    Analysis_Month,
    ROUND(Revenue, 2) AS Revenue,
    ROUND(Expenses, 2) AS Expenses,
    ROUND(Net_Profit, 2) AS Net_Profit,

    ROUND(
        LAG(Net_Profit) OVER (ORDER BY Analysis_Month),
        2
    ) AS Previous_Month_Profit,

    ROUND(
        (Net_Profit - LAG(Net_Profit) OVER (ORDER BY Analysis_Month))
        * 100.0 /
        NULLIF(LAG(Net_Profit) OVER (ORDER BY Analysis_Month), 0),
        2
    ) AS Profit_Change_Percent

FROM Monthly_Performance
ORDER BY Analysis_Month;